                                                                customerInfo.Fax, customerInfo.Closed,
                                                                customerInfo.Suspend, customerInfo.IsEnablePT,
                                                                customerInfo.SIBCCustID, customerInfo.MIBCCustID,
                                                                customerInfo.AIBCCustID, customerInfo.RoleId.ToString(),
                                                                EnableBonus,
                                                                EnableJackpot,
                                                                DateTime.Today,
                                                                ip, userId, userName, 3);
                Thread.Sleep(1000);
